<style>
.checkout-public{padding-top:32px;padding-bottom:55px}.checkout-public .pc-workspace{max-width:1200px}.checkout-public .pc-card{color:var(--pc-ink)}.checkout-public .pc-checkout-layout{display:grid;grid-template-columns:minmax(0,1fr) 365px;gap:26px;align-items:start}.checkout-public .pc-total-row{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;font-size:14px;line-height:1.7;padding:7px 0}.checkout-public .pc-total-row span{color:#667b6e}.checkout-public .pc-total-final{border-top:1px solid #dce7df;margin-top:15px;padding-top:20px;font-size:20px;font-weight:650}.checkout-public .pc-coupon-row{display:flex;align-items:flex-end;gap:9px}.checkout-public .pc-coupon-row label{flex:1;min-width:0}.checkout-public .pc-cart-line{padding:14px 0;border-bottom:1px solid #e3eadf;display:flex;gap:12px;align-items:flex-start;font-size:13px}.checkout-public .pc-cart-line>div{flex:1;min-width:0;overflow-wrap:anywhere}.checkout-public .pc-cart-line img{height:55px;width:55px;border-radius:8px;object-fit:contain;background:#f3f7ec}.checkout-public .pc-checkout-summary{position:sticky;top:110px}.checkout-public .pc-payment{display:flex;gap:10px;align-items:flex-start;border:1px solid #d9e5d8;border-radius:12px;padding:15px;font-size:13px;line-height:1.6}.checkout-public .pc-payment:has(input:checked){background:#edf6e9;border-color:#7d9f79}.checkout-public .pc-payment strong{display:block}.checkout-public .pc-field input{min-height:45px}.checkout-public [data-coupon-remove]{border:0;background:none;color:#226743;text-decoration:underline;font-size:12px;cursor:pointer}.checkout-public .pc-quote-status{margin:14px 0;font-size:12px;line-height:1.7;color:#647969}.checkout-public .pc-quote-status[data-error=true]{color:#a33b30}.checkout-public .pc-review-button{width:100%;margin-top:18px}.checkout-public [hidden]{display:none!important}@media(max-width:950px){.checkout-public .pc-checkout-layout{grid-template-columns:1fr}.checkout-public .pc-checkout-summary{positi